import { useEffect, useState, Fragment } from "react";
import {
	Panel,
	PanelHeader,
	ConfigProvider,
	CardGrid,
	Card,
	HorizontalScroll,
	FormItem,
	Input,
	Footer,
	SimpleCell,
	Avatar,
	Link,
	PanelHeaderButton,
	PanelHeaderContent,
	PanelHeaderContext,
	List,
	Cell,
} from "@vkontakte/vkui";
import {
	Icon28ChevronBack,
	Icon28CoinsOutline,
	Icon56RecentOutline,
	Icon28AddOutline,
	Icon16Dropdown,
	Icon24Done,
	Icon28GhostOutline,
	Icon28FavoriteOutline,
	Icon28FireOutline,
} from "@vkontakte/icons";
const DiceView = (props) => {
	const [visible, setVisible] = useState(false);
	const [balls, setBalls] = useState([]);
	useEffect(() => {
		var res = [];
		for (var i = 0; i < props.result.num; i++) {
			res.push(i);
		}
		setBalls(res);
		setTimeout(() => {
			setVisible(true);
		}, 1200);
	}, []);
	return (
		<div className={`dicesBlock state3 ${visible ? "publish" : ""}`}>
			<div className="diceWrapper">
				<div className="dice n1">
					<div
						className={`face ${
							props.result.num == 6
								? "six"
								: props.result.num == 5
								? "five"
								: props.result.num == 4
								? "four"
								: props.result.num == 3
								? "three"
								: props.result.num == 2
								? "two"
								: "one"
						}`}
					>
						{balls.map(() => {
							return <span className="ball"></span>;
						})}
					</div>
				</div>
			</div>
			{visible && <div className="result">{props.result.num}</div>}
		</div>
	);
};
const Dice2View = (props) => {
	const [visible, setVisible] = useState(false);
	const [balls1, setBalls1] = useState([]);
	const [balls2, setBalls2] = useState([]);
	useEffect(() => {
		var res = [];
		var res1 = [];
		for (var i = 0; i < props.result.nums[0]; i++) {
			res.push(i);
		}
		for (var i = 0; i < props.result.nums[1]; i++) {
			res1.push(i);
		}
		setBalls1(res);
		setBalls2(res1);
		setTimeout(() => {
			setVisible(true);
		}, 1200);
	}, []);
	return (
		<div className={`dicesBlock state3 ${visible ? "publish" : ""}`}>
			<div className="diceWrapper n1">
				<div className="dice">
					<div
						className={`face ${
							props.result.nums[0] == 6
								? "six"
								: props.result.nums[0] == 5
								? "five"
								: props.result.nums[0] == 4
								? "four"
								: props.result.nums[0] == 3
								? "three"
								: props.result.nums[0] == 2
								? "two"
								: "one"
						}`}
					>
						{balls1.map(() => {
							return <span className="ball"></span>;
						})}
					</div>
				</div>
			</div>
			<div className="diceWrapper n2">
				<div className="dice">
					<div
						className={`face ${
							props.result.nums[1] == 6
								? "six"
								: props.result.nums[1] == 5
								? "five"
								: props.result.nums[1] == 4
								? "four"
								: props.result.nums[1] == 3
								? "three"
								: props.result.nums[1] == 2
								? "two"
								: "one"
						}`}
					>
						{balls2.map(() => {
							return <span className="ball"></span>;
						})}
					</div>
				</div>
			</div>
			{visible && (
				<div className="result">
					{props.result.nums[0] + props.result.nums[1]}
				</div>
			)}
		</div>
	);
};
const Dice3View = (props) => {
	const [visible, setVisible] = useState(false);
	const [balls1, setBalls1] = useState([]);
	const [balls2, setBalls2] = useState([]);
	const [balls3, setBalls3] = useState([]);
	useEffect(() => {
		var res = [];
		var res1 = [];
		var res2 = [];
		for (var i = 0; i < props.result.nums[0]; i++) {
			res.push(i);
		}
		for (var i = 0; i < props.result.nums[1]; i++) {
			res1.push(i);
		}
		for (var i = 0; i < props.result.nums[2]; i++) {
			res2.push(i);
		}
		setBalls1(res);
		setBalls2(res1);
		setBalls3(res2);
		setTimeout(() => {
			setVisible(true);
		}, 1200);
	}, []);
	return (
		<div className={`dicesBlock state3 ${visible ? "publish" : ""}`}>
			{visible && (
				<div className="result">
					{props.result.nums[0] + props.result.nums[1] + props.result.nums[2]}
				</div>
			)}
			<div className="diceWrapper n1">
				<div className="dice">
					<div
						className={`face ${
							props.result.nums[0] == 6
								? "six"
								: props.result.nums[0] == 5
								? "five"
								: props.result.nums[0] == 4
								? "four"
								: props.result.nums[0] == 3
